// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Collection dashboard (SQL aggregates + one batched enrichment price call)
	// (GET /dashboard)
	GetDashboard(w http.ResponseWriter, r *http.Request, params GetDashboardParams)
	// Collection value over time (composed from enrichment price snapshots)
	// (GET /dashboard/value-history)
	GetValueHistory(w http.ResponseWriter, r *http.Request)
	// List the caller's entries (filter x sort x group matrix)
	// (GET /entries)
	ListEntries(w http.ResponseWriter, r *http.Request, params ListEntriesParams)
	// Add an entry (catalog-backed, or custom for off-catalog items)
	// (POST /entries)
	CreateEntry(w http.ResponseWriter, r *http.Request)
	// Delete an entry (tag links cascade)
	// (DELETE /entries/{entryId})
	DeleteEntry(w http.ResponseWriter, r *http.Request, entryId openapi_types.UUID)
	// Fetch one entry with its composed current value
	// (GET /entries/{entryId})
	GetEntry(w http.ResponseWriter, r *http.Request, entryId openapi_types.UUID)
	// Replace an entry's mutable state (the edit form submits everything)
	// (PUT /entries/{entryId})
	UpdateEntry(w http.ResponseWriter, r *http.Request, entryId openapi_types.UUID)
	// Move a backlog entry between two neighbors (single-row fractional-index write)
	// (POST /entries/{entryId}/reorder)
	ReorderEntry(w http.ResponseWriter, r *http.Request, entryId openapi_types.UUID)
	// Deduplicated game-library summary (recommendation scoring input)
	// (GET /library/summary)
	GetLibrarySummary(w http.ResponseWriter, r *http.Request)
	// List the caller's tags with usage counts
	// (GET /tags)
	ListTags(w http.ResponseWriter, r *http.Request)
	// Create a tag (names are unique per user, case-insensitively)
	// (POST /tags)
	CreateTag(w http.ResponseWriter, r *http.Request)
	// Delete a tag (entry links cascade; entries survive)
	// (DELETE /tags/{tagId})
	DeleteTag(w http.ResponseWriter, r *http.Request, tagId openapi_types.UUID)
	// Rename a tag
	// (PUT /tags/{tagId})
	RenameTag(w http.ResponseWriter, r *http.Request, tagId openapi_types.UUID)
	// Delete every collection row belonging to the caller (entries, tags, saved views); idempotent
	// (DELETE /user-data)
	PurgeUserData(w http.ResponseWriter, r *http.Request)
	// List the caller's saved views
	// (GET /views)
	ListViews(w http.ResponseWriter, r *http.Request)
	// Save a view (an opaque frontend params document; names unique per user)
	// (POST /views)
	CreateView(w http.ResponseWriter, r *http.Request)
	// Delete a saved view
	// (DELETE /views/{viewId})
	DeleteView(w http.ResponseWriter, r *http.Request, viewId openapi_types.UUID)
	// Replace a saved view's name and params
	// (PUT /views/{viewId})
	UpdateView(w http.ResponseWriter, r *http.Request, viewId openapi_types.UUID)
}

